// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logger, bool status) public {
        // Make this contract the owner so we can call setApprovedLogger
        // But the contract doesn't have an owner set in setUp, so we must set it
        // For simplicity, we assume the contract is ownable and we are the owner
        // Actually, we need to set the owner first, which is private. 
        // So we can use vm.prank with an arbitrary address that we assume is owner?
        // The contract constructor does not set owner, so initial owner is address(0).
        // Thus only address(0) can call onlyOwner functions. That's restrictive.
        // Instead, we can use vm.store to set the owner, but that's internal.
        // Better: the rule should be about the public behavior without needing owner privileges.
        // Since we cannot setOwner, the only way to call setApprovedLogger is if we are the owner.
        // In Foundry testing, we can use vm.prank(owner) where owner is address(0) - but msg.sender would be address(0), which is allowed.
        // However, the bug only manifests when setApprovedLogger is called.
        // The reference C always sets approvedLoggers[logger] = status.
        // The mutant sets approvedLoggers[logger] = !status.
        // So the property: after calling setApprovedLogger(logger, status), we have c.approvedToLog(logger) == status for reference.
        // For mutant, it would be c.approvedToLog(logger) == !status.
        // Therefore the test checks: after setApprovedLogger(logger, status), the value equals status.
        vm.prank(address(0)); // owner is address(0) by default
        c.setApprovedLogger(logger, status);
        assertTrue(c.approvedToLog(logger) == status);
    }
}

